import{St as e,at as t,it as n,ot as r,st as i,t as a,tt as o,vt as s}from"./chunks/framework.B8HA7oqK.js";var c=JSON.parse(`{"title":"Fallback","description":"","frontmatter":{},"headers":[],"relativePath":"ru/config/features/fallback.md","filePath":"ru/config/features/fallback.md","lastUpdated":1779716251000}`),l={name:`ru/config/features/fallback.md`},u={id:`теория-fallbacks`,tabindex:`-1`};function d(a,c,l,d,f,p){let m=e(`Badge`);return s(),n(`div`,null,[c[3]||=t(`<h1 id="fallback" tabindex="-1">Fallback <a class="header-anchor" href="#fallback" aria-label="Permalink to “Fallback”">​</a></h1><blockquote><p><strong>Fallback - одна из самых мощных функций Xray, эффективно предотвращающая активное зондирование и позволяющая свободно настраивать совместное использование нескольких служб на часто используемых портах.</strong></p></blockquote><p>Fallback обеспечивает Xray высокой степенью защиты от активного зондирования и имеет уникальный механизм резервирования первого пакета.</p><p>Fallback также может разделять трафик различных типов по пути, что позволяет совместно использовать один порт для нескольких служб.</p><p>В настоящее время вы можете использовать функцию fallback при использовании протоколов VLESS или Trojan, настроив <code>fallbacks</code>, и создавать очень разнообразные комбинации.</p><h2 id="настроика-fallbacks" tabindex="-1">Настройка <code>fallbacks</code> <a class="header-anchor" href="#настроика-fallbacks" aria-label="Permalink to “Настройка fallbacks”">​</a></h2><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;fallbacks&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: [</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    {</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;dest&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">80</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">  ]</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><blockquote><p><code>fallbacks</code>: [ <a href="#fallbackobject">FallbackObject</a> ]</p></blockquote><p>Массив, содержащий серию мощных конфигураций резервирования и разделения трафика.</p><h3 id="fallbackobject" tabindex="-1">FallbackObject <a class="header-anchor" href="#fallbackobject" aria-label="Permalink to “FallbackObject”">​</a></h3><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;name&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;alpn&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;path&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;dest&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">80</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;xver&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">0</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong><code>fallbacks</code> - это массив, здесь приведено описание конфигурации одного из его элементов.</strong></p><p>Элемент <code>fallbacks</code> является необязательным и может использоваться только для комбинации транспорта TCP+TLS.</p><ul><li>Если этот элемент имеет дочерние элементы, в <a href="./../transports/tls.html#tlsobject">Inbound TLS</a> необходимо установить <code>&quot;alpn&quot;:[&quot;http/1.1&quot;]</code>.</li></ul><p>Обычно сначала нужно настроить набор резервных путей по умолчанию с опущенными или пустыми <code>alpn</code> и <code>path</code>, а затем настроить другие разделения по мере необходимости.</p><p>VLESS будет перенаправлять трафик с длиной первого пакета после дешифрования TLS менее 18 байт, неверной версией протокола или неудачной аутентификацией на адрес, указанный в <code>dest</code>.</p><p>Для других комбинаций транспорта необходимо удалить элемент <code>fallbacks</code> или все его дочерние элементы. В этом случае Fallback не будет включен, VLESS будет ждать считывания необходимой длины, а в случае неверной версии протокола или сбоя аутентификации соединение будет немедленно разорвано.</p><blockquote><p><code>name</code>: string</p></blockquote><p>Попытка сопоставить TLS SNI (указание имени сервера), любое значение или пустая строка, по умолчанию &quot;&quot;.</p><blockquote><p><code>alpn</code>: string</p></blockquote><p>Попытка сопоставить результат согласования TLS ALPN, любое значение или пустая строка, по умолчанию &quot;&quot;.</p><p>При необходимости VLESS попытается прочитать результат согласования TLS ALPN, и в случае успеха выведет в лог <code>realAlpn =</code>. Назначение: решает проблему несовместимости службы h2c Nginx с http/1.1, для которой в Nginx требуется написать две строки listen, по одной для 1.1 и h2c. Примечание: если в <code>fallbacks alpn</code> присутствует <code>&quot;h2&quot;</code>, в <a href="./../transports/tls.html#tlsobject">Inbound TLS</a> необходимо установить <code>&quot;alpn&quot;:[&quot;h2&quot;,&quot;http/1.1&quot;]</code> для поддержки доступа h2.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p><code>alpn</code>, установленный в Fallback, соответствует фактически согласованному ALPN, а <code>alpn</code>, установленный в Inbound TLS, - это список дополнительных ALPN во время рукопожатия. Это разные вещи.</p></div><blockquote><p><code>path</code>: string</p></blockquote><p>Попытка сопоставить HTTP-путь первого пакета, любое значение или пустая строка, по умолчанию пустая строка, если не пустая, то должна начинаться с <code>/</code>, h2c не поддерживается.</p><p>Интеллектуальность: при необходимости VLESS попытается просмотреть PATH (не более 55 байт; самый быстрый алгоритм, не выполняет полный разбор HTTP) и в случае успеха выведет в INFO-лог <code>realPath =</code>. Назначение: разделение трафика WebSocket или HTTP-маскировки для других входящих соединений, без лишней обработки, чистая переадресация трафика, теоретически более высокая производительность, чем у Nginx.</p><p>Примечание: <strong>входящее соединение, в котором находится fallbacks, должно быть TCP+TLS</strong>, это необходимо для разделения трафика на другие входящие соединения WS, входящие соединения, на которые разделяется трафик, не нуждаются в настройке TLS.</p><blockquote><p><code>dest</code>: string | number</p></blockquote><p>Определяет, куда перенаправляется TCP-трафик после дешифрования TLS, в настоящее время поддерживаются два типа адресов (это поле является обязательным, иначе запуск невозможен):</p><ol><li>TCP, формат <code>&quot;addr:port&quot;</code>, где addr поддерживает IPv4, доменное имя, IPv6, если указано доменное имя, TCP-соединение будет установлено напрямую (без использования встроенного DNS).</li><li>Unix domain socket, формат - абсолютный путь, например, <code>&quot;/dev/shm/domain.socket&quot;</code>, в начале можно добавить <code>@</code> для обозначения <a href="https://www.man7.org/linux/man-pages/man7/unix.7.html" target="_blank" rel="noreferrer">abstract</a>, <code>@@</code> - для обозначения abstract с заполнением.</li></ol><p>Если указан только <code>port</code>, можно использовать как число, так и строку, например <code>80</code> или <code>&quot;80&quot;</code>. Обычно это указывает на <code>http</code>-сервис, работающий в открытом виде (<code>addr</code> будет автоматически дополнен как <code>&quot;localhost&quot;</code>).</p><p>Примечание: Начиная с версии <code>v25.7.26</code>, <code>dest</code>, содержащий только <code>port</code>, указывает на <code>localhost</code>, тогда как до этой версии он всегда указывал на <code>127.0.0.1</code>. После этого изменения фактической целью может стать <code>::1</code>. Некоторые шаблоны <code>webserver</code>, скопированные из интернета, могут прослушивать <code>::1</code>, но при этом разрешать доступ только с <code>127.0.0.1</code> или требовать применения <code>proxy protocol</code>, что может привести к различиям в поведении.</p><blockquote><p><code>xver</code>: number</p></blockquote><p>Отправка <a href="https://www.haproxy.org/download/2.2/doc/proxy-protocol.txt" target="_blank" rel="noreferrer">PROXY protocol</a>, специально для передачи реального исходного IP-адреса и порта запроса, заполняется версией 1 или 2, по умолчанию 0, то есть не отправляется. При необходимости рекомендуется указать 1.</p><p>В настоящее время при указании 1 или 2 функциональность полностью идентична, отличается только структура, причем первая может быть распечатана, а вторая - двоичная. Входящие TCP- и WS-соединения Xray уже поддерживают прием PROXY protocol.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Если вы <a href="https://docs.nginx.com/nginx/admin-guide/load-balancer/using-proxy-protocol/#configuring-nginx-to-accept-the-proxy-protocol" target="_blank" rel="noreferrer">настраиваете Nginx на прием PROXY protocol</a>, помимо установки <code>proxy_protocol</code>, необходимо также установить <code>set_real_ip_from</code>, иначе могут возникнуть проблемы.</p></div><h3 id="дополнительные-замечания" tabindex="-1">Дополнительные замечания <a class="header-anchor" href="#дополнительные-замечания" aria-label="Permalink to “Дополнительные замечания”">​</a></h3><ul><li>Будет выполнено сопоставление с наиболее точным дочерним элементом, порядок дочерних элементов не имеет значения. Если настроено несколько дочерних элементов с одинаковыми <code>alpn</code> и <code>path</code>, будет использоваться последний.</li><li>Резервирование и разделение трафика - это переадресация на уровне TCP после дешифрования, а не на уровне HTTP, проверка PATH первого пакета выполняется только при необходимости.</li><li>Вы можете просмотреть больше советов и рекомендаций по использованию Fallbacks: <ul><li><a href="./../../document/level-1/fallbacks-lv1.html">Краткое описание функции Fallbacks</a></li></ul></li></ul>`,38),o(`h2`,u,[c[0]||=r(`Теория Fallbacks `,-1),i(m,{text:`В разработке`,type:`warning`}),c[1]||=r(),c[2]||=o(`a`,{class:`header-anchor`,href:`#теория-fallbacks`,"aria-label":`Permalink to “Теория Fallbacks”`},`​`,-1)])])}var f=a(l,[[`render`,d]]);export{c as __pageData,f as default};